mapper.select:
SELECT id, tenant_id, client_id, capability_id, idempotency_key_hash,
       request_id, response_snapshot, expires_at, del_flag
FROM ai_capability_openapi_idempotency
WHERE tenant_id = #{tenantId}
  AND client_id = #{clientId}
  AND capability_id = #{capabilityId}
  AND idempotency_key_hash = #{keyHash}
  AND del_flag = 0
  AND expires_at > NOW()
LIMIT 1

mapper.delete:
DELETE FROM ai_capability_openapi_idempotency
WHERE expires_at < NOW()
LIMIT #{limit}
